import Foundation

enum WordPackFacts {
    static func apply(
        _ word: StarterWord,
        pack: String,
        index: Int,
        learning: String,
        native: String
    ) -> StarterWord {
        guard let rows = table[pack], rows.indices.contains(index) else { return word }
        let row = rows[index]
        var copy = word
        copy.example = row.example[learning]
        copy.explanation = row.explain[native] ?? row.explain["English"]
        copy.collocations = row.collo[learning] ?? []
        copy.synonyms = row.syn[learning] ?? []
        copy.antonyms = row.ant[learning] ?? []
        return copy
    }

    private struct Row {
        var example: [String: String]
        var explain: [String: String]
        var collo: [String: [String]]
        var syn: [String: [String]]
        var ant: [String: [String]]
    }

    private static let table: [String: [Row]] = load()

    private static func load() -> [String: [Row]] {
        let data = Data(json.utf8)
        let raw = (try? JSONDecoder().decode([String: [Raw]].self, from: data)) ?? [:]
        return raw.mapValues { rows in
            rows.map {
                Row(example: $0.example, explain: $0.explain, collo: $0.collo, syn: $0.syn ?? [:], ant: $0.ant ?? [:])
            }
        }
    }

    private struct Raw: Decodable {
        var example: [String: String]
        var explain: [String: String]
        var collo: [String: [String]]
        var syn: [String: [String]]?
        var ant: [String: [String]]?
    }

